 )
 select coalesce(displays->>regexp_replace(lower(raw_name),'[[:space:]]','','g'),
   names->>regexp_replace(lower(btrim(raw_name)),'[[:space:]]*[-‐‑‒–—﹘﹣－][[:space:]]*','-','g'),
   displays->>regexp_replace(lower(base_name),'[[:space:]]','','g'),
   names->>regexp_replace(lower(btrim(base_name)),'[[:space:]]*[-‐‑‒–—﹘﹣－][[:space:]]*','-','g'),base_name) from aliases;
$function$;
